  overlapChars: 150,            // đoạn sau lặp lại 150 ký tự cuối của đoạn trước để không mất ngữ cảnh
  minChars: 40,                 // đoạn ngắn hơn mức này bị gộp/bỏ
  batchSize: 10,                // gửi 10 đoạn / 1 lần gọi API embedding
  maxTextChars: 1000000,        // lưu tối đa 1 triệu ký tự văn bản gốc vào documents.extracted_text
