const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const s = (v, max = 500) => (v === undefined || v === null ? '' : String(v).trim().slice(0, max));
const safe = (fn, fallback = null) => { try { const v = fn(); return v === undefined ? fallback : v; } catch (e) { return fallback; } };
const newUuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});
const CATEGORIES = ['product', 'policy', 'faq', 'pricing', 'general'];// WF-09 | Stage 8 - turn the PDF text into overlapping chunks (~1000 chars) that remember their page numbers.
const c = $('02 Config and Mode').item.json;
const L = c.config.limits;
const up = $('04 Validate Upload').first().json;
const ex = $json;

const fail = (httpCode, code, message) => ({ json: { ok: false, httpCode, errors: [{ field: 'file', code, message }], correlationId: up.correlationId } });

if (ex.error || ex.text === undefined) {
  const msg = s(ex.error && (ex.error.message || ex.error), 200);
  return fail(422, /password/i.test(msg) ? 'PDF_ENCRYPTED' : 'PDF_UNREADABLE', 'Không đọc được PDF' + (msg ? ': ' + msg : '') + '. File có thể bị hỏng hoặc đặt mật khẩu.');
}

const rawPages = Array.isArray(ex.text) ? ex.text : [String(ex.text || '')];
const cleanPage = (t) => String(t || '')
  .normalize('NFC').replace(/\r/g, '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, ' ')
  .replace(/(^|\s)([A-Za-z]+)-\n([A-Za-z]+)(?=[\s.,;:!?)]|$)/g, '$1$2$3')   // English "inter-\nnational" -> "international" (whole words must be plain A-Z, so Vietnamese is never touched)
  .split('\n').map((l) => l.replace(/[ \t]+/g, ' ').trim())
  .filter((l) => l && !/^(trang|page)?\s*\d{1,3}(\s*\/\s*\d{1,3})?$/i.test(l))  // lone page numbers
  .join('\n');
const pages = rawPages.map(cleanPage);
const fullText = pages.join('\n\n').trim();

if (fullText.length < L.minChars) {
  return fail(422, 'NO_TEXT', 'PDF không có văn bản đọc được (có thể là file scan/ảnh). Cần chạy OCR (WF-10) trước rồi mới nạp vào kho tri thức.');
}

// ---- split every page into "units" (lines; very long lines are cut at sentence/word boundaries)
const units = [];
pages.forEach((pt, pi) => {
  for (const line of pt.split('\n')) {
    if (line.length <= L.chunkChars) { units.push({ t: line, p: pi + 1 }); continue; }
    let rest = line;
    while (rest.length > L.chunkChars) {
      let cut = -1;
      for (const m of rest.slice(0, L.chunkChars).matchAll(/[.!?…;:]\s/g)) cut = m.index + 1;
      if (cut < L.chunkChars * 0.4) cut = rest.lastIndexOf(' ', L.chunkChars);
      if (cut < L.chunkChars * 0.4) cut = L.chunkChars;
      units.push({ t: rest.slice(0, cut).trim(), p: pi + 1 });
      rest = rest.slice(cut).trim();
    }
    if (rest) units.push({ t: rest, p: pi + 1 });
  }
});

// ---- greedy packing with overlap
const chunks = [];
let buf = [];
let len = 0;
let fresh = 0;                                   // units added since the last emitted chunk (ignores pure-overlap leftovers)
const emit = () => {
  if (!fresh) return;
  const content = buf.map((u) => u.t).join('\n');
  chunks.push({ content, pageStart: buf[0].p, pageEnd: buf[buf.length - 1].p });
};
for (const u of units) {
  if (len + u.t.length + 1 > L.chunkChars && fresh) {
    emit();
    const keep = [];
    let l = 0;
    for (let i = buf.length - 1; i >= 0; i--) {
      if (l + buf[i].t.length + 1 > L.overlapChars) break;
      keep.unshift(buf[i]); l += buf[i].t.length + 1;
    }
    buf = keep; len = l; fresh = 0;
  }
  buf.push(u); len += u.t.length + 1; fresh++;
}
emit();

// tiny last chunk -> glue to the previous one
if (chunks.length > 1 && chunks[chunks.length - 1].content.length < L.minChars) {
  const last = chunks.pop();
  const prev = chunks[chunks.length - 1];
  prev.content += '\n' + last.content; prev.pageEnd = last.pageEnd;
}
const finalChunks = chunks.filter((x) => x.content.length >= Math.min(L.minChars, fullText.length)).map((x, i) => ({
  index: i, content: x.content, pageStart: x.pageStart, pageEnd: x.pageEnd, chars: x.content.length, approxTokens: Math.ceil(x.content.length / 3.5),
}));

if (finalChunks.length > L.maxChunks) {
  return fail(413, 'TOO_MANY_CHUNKS', 'Tài liệu tạo ra ' + finalChunks.length + ' đoạn, vượt giới hạn ' + L.maxChunks + '. Hãy tách PDF thành các file nhỏ hơn.');
}

// ---- fingerprint of the text (used to detect "same document uploaded twice")
const hash = (str) => {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
};

return {
  json: {
    ok: true, chunks: finalChunks, pageCount: Number(ex.numpages) || pages.length, charCount: fullText.length,
    textHash: hash(fullText) + ':' + fullText.length, extractedText: fullText.slice(0, L.maxTextChars),
    pdfInfo: { title: s(ex.info && ex.info.Title, 200), author: s(ex.info && ex.info.Author, 200) },
  },
};

